-- Function: public.fn_get_platform_organization_admins
-- Backup generated on 2026-10-25 20:33:38

CREATE OR REPLACE FUNCTION public.fn_get_platform_organization_admins()  RETURNS TABLE(user_id uuid, admin_name text, admin_email character varying, organization_id uuid, organization_name character varying, role_name character varying, account_status text)  LANGUAGE sql  STABLE AS $function$     SELECT DISTINCT ON (o.id, COALESCE(u.id, '00000000-0000-0000-0000-000000000000'::uuid))         COALESCE(u.id, gen_random_uuid()) AS user_id,         CASE              WHEN u.display_name IS NOT NULL AND TRIM(u.display_name) != '' AND TRIM(u.display_name) != o.name THEN TRIM(u.display_name)             WHEN TRIM(CONCAT(u.first_name, ' ', u.last_name)) != '' AND TRIM(CONCAT(u.first_name, ' ', u.last_name)) != 'Admin' AND TRIM(CONCAT(u.first_name, ' ', u.last_name)) != o.name THEN TRIM(CONCAT(u.first_name, ' ', u.last_name))             WHEN u.email IS NOT NULL AND u.email != '' THEN INITCAP(SPLIT_PART(SPLIT_PART(u.email, '@', 1), '.', 1))             ELSE 'Daycare Director'         END AS admin_name,         COALESCE(u.email, 'admin@daycare.org') AS admin_email,         o.id AS organization_id,         o.name AS organization_name,         COALESCE(r.name, 'Organization Admin') AS role_name,         CASE WHEN o.is_active THEN 'Active' ELSE 'Suspended' END AS account_status     FROM organizations o     LEFT JOIN organization_memberships om ON om.organization_id = o.id AND om.status = 'Active'     LEFT JOIN users u ON u.id = om.user_id     LEFT JOIN user_organization_roles uor ON uor.user_id = u.id AND uor.organization_id = o.id     LEFT JOIN roles r ON r.id = uor.role_id     ORDER BY o.id, COALESCE(u.id, '00000000-0000-0000-0000-000000000000'::uuid),               CASE WHEN r.name = 'OrganizationOwner' THEN 1 WHEN r.name = 'OrganizationAdmin' THEN 2 ELSE 3 END; $function$ ;
